import json
def serve(inp,out):
    eof=object();pending={}
    def packet():
        header=inp.read(4)
        if not header:return eof
        if len(header)!=4 or any(c not in b'0123456789abcdefABCDEF' for c in header):raise ValueError('pkt-line header')
        length=int(header,16)
        if length==0:return None
        if not 4<=length<=65520:raise ValueError('pkt-line size')
        value=inp.read(length-4)
        if len(value)!=length-4:raise ValueError('short pkt-line')
        return value
    def group():
        result=[]
        while True:
            value=packet()
            if value is eof:
                if result:raise ValueError('unexpected EOF')
                return eof
            if value is None:return result
            result.append(value)
            if sum(map(len,result))>1048576:raise ValueError('request budget')
    def write_group(values):
        for value in values:
            if len(value)>65516:raise ValueError('output packet budget')
            out.write(('%04x'%(len(value)+4)).encode()+value)
        out.write(b'0000');out.flush()
    if group()!=[b'git-filter-client\n',b'version=2\n']:raise ValueError('filter v2 required')
    write_group([b'git-filter-server\n',b'version=2\n'])
    offered=group()
    if offered is eof:raise ValueError('capabilities missing')
    write_group([value for value in offered if value in (b'capability=clean\n',b'capability=smudge\n',b'capability=delay\n')])
    while True:
        headers=group()
        if headers is eof:return
        fields=dict(value.rstrip(b'\n').split(b'=',1) for value in headers)
        command=fields.get(b'command')
        if command==b'list_available_blobs':
            write_group([b'pathname='+path+b'\n' for path in pending])
            write_group([b'status=success\n']);continue
        content=group()
        if content is eof:raise ValueError('request content missing')
        content=b''.join(content);path=fields.get(b'pathname',b'')
        try:
            if command not in (b'clean',b'smudge') or path.rsplit(b'/',1)[-1]==b'offline.json':raise ValueError('conversion unavailable')
            if command==b'smudge' and path in pending and not content:result=pending.pop(path)
            elif not content:result=b''
            else:
                value=json.loads(content.decode('utf8'))
                result=(json.dumps(value,ensure_ascii=False,sort_keys=True,**({'separators':(',',':')} if command==b'clean' else {'indent':2}))+'\n').encode('utf8')
            if command==b'smudge' and path.rsplit(b'/',1)[-1].startswith(b'deferred') and fields.get(b'can-delay')==b'1':
                pending[path]=result;write_group([b'status=delayed\n']);continue
        except (ValueError,UnicodeError):write_group([b'status=error\n']);continue
        write_group([b'status=success\n'])
        write_group([result[i:i+65516] for i in range(0,len(result),65516)])
        write_group([])
